R=Path('Code2');C=R/'Code2.cpp';P=R/'PROGRESS.md';A=R/'CODE2_CONTINUITY_ADDENDUM.md';K=R/'RESUME_CHECKPOINT.md';F=R/'.batch100.fragment.cpp'
